// n8n Code node: Convert standard markdown to Slack mrkdwn
// Input: $json.output (markdown string)
// Output: { output: string } (slack mrkdwn string)

// Stash fenced code blocks and inline code spans as private-use placeholders so
// inline transforms never touch literal code content. Two separate stores so
// inline spans can be restored before table layout (accurate column widths)
// while fenced blocks stay protected until the very end.
function stash(store, sentinel) {
  return (s) => {
    store.push(s);
    return sentinel[0] + (store.length - 1) + sentinel[1];
  };
}

function restore(text, store, sentinel) {
  const re = new RegExp(sentinel[0] + '(\\d+)' + sentinel[1], 'g');
  return text.replace(re, (_, i) => store[Number(i)]);
}

const FENCE = ['\uE000', '\uE001'];
const SPAN = ['\uE002', '\uE003'];

function markdownTableToSlack(tableStr) {
  const rows = tableStr.trim().split('\n');
  const dataRows = rows.filter(r => !/^\|[\s\-:|]+\|$/.test(r.trim()));

  const parsed = dataRows.map(row =>
    row.trim().split('|').slice(1, -1).map(cell => cell.trim())
  );

  if (parsed.length === 0) return tableStr;

  const colWidths = parsed[0].map((_, colIdx) =>
    Math.max(...parsed.map(row => (row[colIdx] || '').length))
  );

  const formatted = parsed.map(row =>
    row.map((cell, colIdx) => cell.padEnd(colWidths[colIdx])).join('  ').trimEnd()
  );

  const separator = colWidths.map(w => '-'.repeat(w)).join('--');
  formatted.splice(1, 0, separator);

  return '```\n' + formatted.join('\n') + '\n```';
}

const input = $json.output ?? '';
const fences = [];
const spans = [];
let text = input;

// 0. Protect code: fenced blocks first, then inline spans
text = text.replace(/```[\s\S]*?```/g, stash(fences, FENCE));
text = text.replace(/`[^`\n]+`/g, stash(spans, SPAN));

// 1. Horizontal rules: --- → blank line (safe now: code blocks are stashed)
text = text.replace(/^-{3,}$/gm, '');

// 2. Headers: strip inner emphasis (bold BEFORE italic so ** pairs are not
//    partially matched), then wrap the whole header in *bold*
text = text.replace(/^#{1,6}\s+(.+)$/gm, (_, content) => {
  const stripped = content
    .replace(/\*\*(.+?)\*\*/g, '$1')
    .replace(/\*(.+?)\*/g, '$1');
  return '*' + stripped + '*';
});

// 3. Bold: **text** → *text*
text = text.replace(/\*\*(.+?)\*\*/g, '*$1*');

// 4. Links: [text](url) → <url|text>
text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<$2|$1>');

// 5. Block quotes: > text → plain text
text = text.replace(/^>\s?(.+)$/gm, '$1');

// 6. Strikethrough: ~~text~~ → ~text~
text = text.replace(/~~(.+?)~~/g, '~$1~');

// 7. Restore inline code spans now so table column widths are computed on the
//    final cell text. Fenced blocks stay stashed (they cannot be table rows).
text = restore(text, spans, SPAN);

// 8. Tables → fenced monospace blocks (cells are already fully converted, so
//    padding matches what Slack renders)
text = text.replace(
  /(?:^|\n)(\|.+\|[ \t]*\n\|[\s\-:|]+\|[ \t]*\n(?:\|.+\|[ \t]*\n?)+)/g,
  (match) => '\n' + markdownTableToSlack(match) + '\n'
);

// 9. Clean up excessive blank lines (3+ → 2)
text = text.replace(/\n{3,}/g, '\n\n');

// 10. Restore fenced code blocks
text = restore(text, fences, FENCE);

return { output: text };
